glsl3.vert:
precision highp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};

in vec3 a_position;
in vec4 a_color;
out vec4 v_color;

#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif

void main () {
  vec4 pos = vec4(a_position, 1);
  pos = cc_matViewProj * pos;

  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif

  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;

in vec4 v_color;

#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif

uniform PROPERTIES {
  vec4 glowColor;
  vec4 glowAlpha;
  vec4 glowSpread;
  vec4 texCoordRect;
  float texCoordFlipY;
  float colorAdjustEnabled;
  float hueShift;
  float saturationMul;
  float valueMul;
  float colorAdjustStrength;
  float colorAdjustWhiteProtect;
};

vec3 rgbToYiq(vec3 rgb) {
  return vec3(
    dot(rgb, vec3(0.299, 0.587, 0.114)),
    dot(rgb, vec3(0.596, -0.274, -0.322)),
    dot(rgb, vec3(0.211, -0.523, 0.312))
  );
}

vec3 yiqToRgb(vec3 yiq) {
  return clamp(vec3(
    yiq.x + 0.956 * yiq.y + 0.621 * yiq.z,
    yiq.x - 0.272 * yiq.y - 0.647 * yiq.z,
    yiq.x - 1.106 * yiq.y + 1.703 * yiq.z
  ), 0.0, 1.0);
}

vec3 applyPsHueYiq(vec3 rgb, float hueShiftVal) {
  vec3 yiq = rgbToYiq(max(rgb, vec3(0.0)));
  float chroma = length(yiq.yz);
  float hue = chroma > 1.0e-5 ? atan(yiq.z, yiq.y) : 0.0;
  hue += hueShiftVal * 6.28318530718;
  yiq.yz = vec2(cos(hue), sin(hue)) * chroma;
  return yiqToRgb(yiq);
}

vec3 applyPsSaturationRec709(vec3 rgb, float sat) {
  float s = max(0.0, sat);
  vec3 safe = max(rgb, vec3(0.0));
  float luma = dot(safe, vec3(0.2125, 0.7154, 0.0721));
  return mix(vec3(luma), safe, s);
}

float bakedRec709Luminance(vec3 rgb) {
  return dot(max(rgb, vec3(0.0)), vec3(0.2126, 0.7152, 0.0722));
}

vec3 applyCompanionValueScale(vec3 sourceRgb, float valueMul, float strength) {
  float s = clamp(strength, 0.0, 1.0);
  float vm = clamp(valueMul, 0.0, 1.0);
  vec3 safe = max(sourceRgb, vec3(0.0));
  if (s <= 0.00001) {
    return safe;
  }
  float luma = bakedRec709Luminance(safe);
  float yScaled = vm;
  vec3 adjusted = clamp(vec3(yScaled) + (safe - luma), 0.0, 1.0);
  return mix(safe, adjusted, s);
}

vec3 applyBakedColorAdjustSplit(vec3 sourceRgb, float hueShift, float saturationMul, float valueMul, float hueSatWeight, float valueWeight) {
  float s = clamp(hueSatWeight, 0.0, 1.0);
  float vw = clamp(valueWeight, 0.0, 1.0);
  vec3 safe = max(sourceRgb, vec3(0.0));
  vec3 rgb = safe;
  vec3 hued = applyPsHueYiq(safe, hueShift);
  vec3 satd = applyPsSaturationRec709(hued, saturationMul);
  rgb = mix(rgb, satd, s);
  rgb = applyCompanionValueScale(rgb, valueMul, vw);
  return rgb;
}

void main () {
  vec4 o = vec4(1.0, 1.0, 1.0, 1.0);

  #if USE_TEXTURE
    o *= texture2D(texture, v_uv0);
  #endif

  #if CC_USE_ALPHA_ATLAS_TEXTURE
    o.a *= texture2D(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif

  o *= v_color;

  vec2 localUV = v_uv0;
  #if USE_TEXTURE
    vec2 rectMin = texCoordRect.xy;
    vec2 rectSize = max(texCoordRect.zw, vec2(1.0e-5));
    localUV = (v_uv0 - rectMin) / rectSize;
    if (texCoordFlipY > 0.5) {
      localUV.y = 1.0 - localUV.y;
    }
    localUV = clamp(localUV, vec2(0.0), vec2(1.0));
  #endif

  float spread = clamp(glowSpread.x, 0.0, 0.98);
  float featherY = clamp(glowSpread.y, 0.02, 0.5);
  float spreadXMul = clamp(glowSpread.z, 0.0, 1.0);
  float featherX = clamp(glowSpread.w, 0.02, 0.5);
  float cardCenterY = glowAlpha.y > 0.001 ? clamp(glowAlpha.y, 0.04, 0.96) : 0.5;
  float edgeMargin = clamp(glowAlpha.z, 0.02, 0.22);

  float headroomUp = max(cardCenterY, 0.04);
  float headroomDown = max(1.0 - cardCenterY, 0.04);
  float distY = localUV.y < cardCenterY
    ? (cardCenterY - localUV.y) / headroomUp
    : (localUV.y - cardCenterY) / headroomDown;
  float distX = abs(localUV.x - 0.5) * 2.0;
  float fadeEndY = min(0.999, max(spread + featherY, spread + 0.02));
  float maskY = 1.0 - smoothstep(spread, fadeEndY, distY);
  float spreadX = spread * spreadXMul;
  float fadeEndX = min(0.999, max(spreadX + featherX, spreadX + 0.02));
  float maskX = 1.0 - smoothstep(spreadX, fadeEndX, distX);
  float vertEdge = smoothstep(0.0, edgeMargin, localUV.y) * smoothstep(1.0, 1.0 - edgeMargin, localUV.y);
  float mask = maskY * maskX * vertEdge;

  float alphaMul = clamp(glowAlpha.x, 0.0, 1.0);
  o.rgb *= glowColor.rgb;
  o.a *= alphaMul * glowColor.a * mask;

  if (colorAdjustEnabled > 0.5 && o.a > 0.001) {
    vec3 sourceRgb = o.rgb;
    float strength = clamp(colorAdjustStrength, 0.0, 1.0);
    o.rgb = applyBakedColorAdjustSplit(sourceRgb, hueShift, saturationMul, valueMul, strength, strength);
  }

  gl_FragColor = o;
}

